'use strict';

// MODULES //

var logger = require( 'debug' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'markdown-to-semantic-document:classify-html' );
var SECTION_OPEN_RE = /^\s*<section\s+class=(?:"([^"]+)"|'([^']+)')\s*>\s*$/;
var SECTION_CLOSE_RE = /^\s*<\/section>\s*$/;
var SECTION_END_RE = /^\s*<!--\s*\/\.([A-Za-z0-9_-]+)\s*-->\s*$/;
var RUN_DISABLE_RE = /^\s*<!--\s*run-disable\s*-->\s*$/;
var RUN_RE = /^\s*<!--\s*run:\s*([\s\S]*?)\s*-->\s*$/;
var ESLINT_RE = /^\s*<!--\s*eslint(-disable|-enable)?(?:\s+([\s\S]*?))?\s*-->\s*$/;
var EQUATION_RE = /^\s*<!--\s*<equation\b([\s\S]*?)>\s*-->\s*$/;
var LICENSE_RE = /^\s*<!--[\s\S]*@license\s+[A-Za-z0-9.-]+[\s\S]*-->\s*$/;
var LINKS_RE = /^\s*<!--\s*links\s*-->\s*$/;
var COMMENT_RE = /^\s*<!--[\s\S]*-->\s*$/;


// FUNCTIONS //

/**
* Returns an HTML attribute value.
*
* @private
* @param {string} value - attribute source
* @param {string} name - attribute name
* @returns {(string|null)} attribute value
*/
function attribute( value, name ) {
	var match;
	var re;

	re = new RegExp( format( '(?:^|\\s)%s=(?:"([^"]*)"|\'([^\']*)\')', name ) );
	match = re.exec( value );
	if ( !match ) {
		return null;
	}
	return ( match[ 1 ] === void 0 ) ? match[ 2 ] : match[ 1 ];
}

/**
* Tests whether a comment is a recognized maintenance comment.
*
* @private
* @param {string} value - HTML comment
* @returns {boolean} boolean indicating whether a comment is maintenance markup
*/
function isMaintenance( value ) {
	return (
		/Make sure to keep an empty line/i.test( value ) ||
		/Do not manually edit this section/i.test( value ) ||
		/^\s*<!--\s*(?:C|CLI)/i.test( value ) ||
		/^\s*<!--\s*Section/i.test( value ) ||
		/^\s*<!--\s*Package/i.test( value ) ||
		/^\s*<!--\s*Example/i.test( value )
	);
}

/**
* Logs and returns an HTML classification.
*
* @private
* @param {Object} out - HTML classification
* @returns {Object} HTML classification
*/
function result( out ) {
	debug( 'Classified standalone HTML: type=%s', out.type );
	return out;
}


// MAIN //

/**
* Classifies a standalone raw HTML block.
*
* @private
* @param {string} value - raw HTML
* @returns {Object} classification
*/
function classify( value ) {
	var match;

	// Test structural wrappers first. These exact, standalone forms are consumed by the document structure pass rather than emitted as raw HTML...
	match = SECTION_OPEN_RE.exec( value );
	if ( match ) {
		return result({
			'type': 'section-open',
			'name': match[ 1 ] || match[ 2 ]
		});
	}
	if ( SECTION_CLOSE_RE.test( value ) ) {
		return result({
			'type': 'section-close'
		});
	}
	match = SECTION_END_RE.exec( value );
	if ( match ) {
		return result({
			'type': 'section-end',
			'name': match[ 1 ]
		});
	}
	// Run and ESLint comments have execution semantics. Matching is intentionally strict so that ordinary prose comments are never treated as directives...
	if ( RUN_DISABLE_RE.test( value ) ) {
		return result({
			'type': 'run-disable',
			'raw': value
		});
	}
	match = RUN_RE.exec( value );
	if ( match ) {
		return result({
			'type': 'run',
			'raw': value,
			'value': match[ 1 ]
		});
	}
	match = ESLINT_RE.exec( value );
	if ( match ) {
		return result({
			'type': 'eslint',
			'raw': value,
			'action': ( match[ 1 ] ) ? match[ 1 ].slice( 1 ) : 'configure',
			'value': match[ 2 ] || ''
		});
	}
	// An equation sequence consists of metadata, a math fence, optional rendered fallback markup, and a close marker. Classify the pieces independently so that the converter can validate their ordering without discarding orphans...
	match = EQUATION_RE.exec( value );
	if ( match ) {
		return result({
			'type': 'equation-open',
			'label': attribute( match[ 1 ], 'label' ),
			'alt': attribute( match[ 1 ], 'alt' )
		});
	}
	if ( /^\s*<!--\s*<\/equation>\s*-->\s*$/i.test( value ) ) {
		return result({
			'type': 'equation-close'
		});
	}
	if ( /^\s*<!--\s*<\/?div\b[^>]*\bequation\b/i.test( value ) ) {
		return result({
			'type': 'equation-fallback'
		});
	}
	if ( /^\s*<!--\s*<\/?related-links>\s*-->\s*$/.test( value ) ) {
		return result({
			'type': 'related-links-marker'
		});
	}
	if ( LINKS_RE.test( value ) ) {
		return result({
			'type': 'links-marker'
		});
	}
	// License and template comments are characterized for stdlib-aware profiles. Generic conversion preserves these classifications as raw semantic flow...
	if ( LICENSE_RE.test( value ) ) {
		return result({
			'type': 'license'
		});
	}
	if ( COMMENT_RE.test( value ) && isMaintenance( value ) ) {
		return result({
			'type': 'maintenance-comment'
		});
	}
	return result({
		'type': 'unknown'
	});
}


// EXPORTS //

module.exports = classify;
